40	// Percent-based arithmetic (× 110 ÷ 100) rather than a float rate (× 1.1):
41	// it keeps intermediate values integral and avoids binary floating-point
42	// error — 100 * 1.1 is 110.00000000000001, but (100 * 110) / 100 is exact.
43	const FIRST_INSURANCE_PERCENT_OF_BASE = 110;
44	const ADMIN_FEE = 5;
45	
46	const quote = (step: QuoteStep): QuoteResult => {
47	  const basePremium = BASE_PREMIUMS[step.items[0].type];
48	  const premiumAfterFirstInsurance =
49	    (basePremium * FIRST_INSURANCE_PERCENT_OF_BASE) / 100;
50	  return { premium: premiumAfterFirstInsurance + ADMIN_FEE };
51	};
52	
53	export const runScenario = (scenario: Scenario): ScenarioResult => {
54	  return { results: scenario.steps.map(quote) };
55	};
